#include <iostream>

// main.cpp's translation unit, as the preprocessor builds it.
// #include "fees.h" pastes fees.h here:
#ifndef FEES_H
#define FEES_H
const double kFeeRate = 0.0005;  // a constant defined in the header
double feeFor(double notional);
#endif

// #include "orders.h" pastes orders.h, which starts with its own #include "fees.h":
#ifndef ORDERS_H
#define ORDERS_H
#ifndef FEES_H                   // already defined, so this copy is skipped
#define FEES_H
const double kFeeRate = 0.0005;
double feeFor(double notional);
#endif
int lotsFor(int shares);
#endif

int main() {
    std::cout << "rate: " << kFeeRate << '\n';
    std::cout << "fee on 20000: " << feeFor(20000.0) << '\n';
    std::cout << "lots in 350 shares: " << lotsFor(350) << '\n';
    return 0;
}

// fees.cpp and orders.cpp are separate translation units. Their definitions:
double feeFor(double notional) {
    return notional * kFeeRate;
}

int lotsFor(int shares) {
    return shares / 100;
}

