#include <iostream>

// What fills.h would hold: declarations only.
extern int g_fills;           // an int named g_fills is defined somewhere
void recordFill(int qty);     // so are these two functions
int averageQty();

void recordFill(int qty);     // repeating a declaration is fine

int main() {
    recordFill(100);
    recordFill(250);
    recordFill(30);
    std::cout << "fills: " << g_fills << '\n';
    std::cout << "average qty: " << averageQty() << '\n';
    return 0;
}

// What fills.cpp would hold: the one definition of each.
int g_fills = 0;
int g_totalQty = 0;

void recordFill(int qty) {
    ++g_fills;
    g_totalQty += qty;
}

int averageQty() {
    return g_fills == 0 ? 0 : g_totalQty / g_fills;
}

