#include <iostream>

// Internal linkage: no other translation unit can see these two names.
static double roundCents(double x) {
    return static_cast<long long>(x * 100.0 + 0.5) / 100.0;
}

namespace {
    int feeCalls = 0;
}

// inline: a header may define it, and every file that includes it gets a copy.
inline double toBps(double fraction) {
    return fraction * 10000.0;
}

// External linkage, the default: any translation unit can call it.
double feeFor(double notional) {
    ++feeCalls;
    return roundCents(notional * 0.00035);
}

int main() {
    std::cout << "fee on 12345: " << feeFor(12345.0) << '\n';
    std::cout << "fee on 800: " << feeFor(800.0) << '\n';
    std::cout << "rate: " << toBps(0.00035) << " bps\n";
    std::cout << "fee calls: " << feeCalls << '\n';
    return 0;
}

